import React, { useState, useEffect } from "react";
import API from "../utils/axiosInstance";
import { Container, Table, Button, Form, Modal, Spinner } from "react-bootstrap";

const AdminDashboard = () => {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [currentEventId, setCurrentEventId] = useState(null);
  const [newEvent, setNewEvent] = useState({
    title: "",
    description: "",
    date: "",
  });
  const [registrants, setRegistrants] = useState([]);
  const [showRegistrantsModal, setShowRegistrantsModal] = useState(false);
  const [loadingRegistrants, setLoadingRegistrants] = useState(false);

  // Fetch Events
  const fetchEvents = async () => {
    try {
      const response = await API.get("/events/admin-events");
      setEvents(response.data);
    } catch (error) {
      console.error("Error fetching events:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  // Fetch Registrants for a specific event
  const fetchRegistrants = async (eventId) => {
    setLoadingRegistrants(true);
    setRegistrants([]);
    try {
      const response = await API.get(`/events/${eventId}/registrants`);
      setRegistrants(response.data);
    } catch (error) {
      console.error("Error fetching registrants:", error);
    } finally {
      setLoadingRegistrants(false);
      setShowRegistrantsModal(true);
    }
  };

  // Show Modal for Creating or Editing Events
  const handleShowModal = (event = null) => {
    if (event) {
      setEditMode(true);
      setCurrentEventId(event._id);
      setNewEvent({
        title: event.title,
        description: event.description,
        date: event.date.split("T")[0], // Fix date format
      });
    } else {
      setEditMode(false);
      setCurrentEventId(null);
      setNewEvent({ title: "", description: "", date: "" });
    }
    setShowModal(true);
  };

  const handleCloseModal = () => setShowModal(false);

  return (
    <Container className="admin-dashboard-container mt-5">
      <h2 className="text-center mb-4">Admin Dashboard</h2>

      {loading ? (
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
      ) : (
        <Table striped bordered hover>
          <thead>
            <tr>
              <th>Title</th>
              <th>Description</th>
              <th>Date</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {events.map((event) => (
              <tr key={event._id}>
                <td>{event.title}</td>
                <td>{event.description}</td>
                <td>{new Date(event.date).toLocaleDateString()}</td>
                <td>
                  <Button
                    variant="info"
                    onClick={() => fetchRegistrants(event._id)}
                    className="me-2"
                  >
                    <i className="bi bi-eye"></i> View Registrants
                  </Button>
                  <Button
                    variant="warning"
                    onClick={() => handleShowModal(event)}
                    className="me-2"
                  >
                    Edit
                  </Button>
                  <Button variant="danger" onClick={() => handleDelete(event._id)}>
                    Delete
                  </Button>
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}

      <Button variant="primary" onClick={() => handleShowModal()}>
        Create New Event
      </Button>

      {/* Registrants Modal */}
      <Modal show={showRegistrantsModal} onHide={() => setShowRegistrantsModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Registrants for the Event</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {loadingRegistrants ? (
            <Spinner animation="border" role="status">
              <span className="visually-hidden">Loading...</span>
            </Spinner>
          ) : (
            <ul>
              {registrants.length > 0 ? (
                registrants.map((registrant) => <li key={registrant._id}>{registrant.name}</li>)
              ) : (
                <p>No registrants for this event.</p>
              )}
            </ul>
          )}
        </Modal.Body>
      </Modal>
    </Container>
  );
};

export default AdminDashboard;
